# -------------------- Semaphore Guard Tests --------------------

class TestSemaphoreGuard:
    """Validation of concurrency limiting."""

    @pytest.mark.asyncio
    async def test_concurrency_limit(self):
        """Verify semaphore enforces max concurrency."""
        semaphore = asyncio.Semaphore(2)
        active = 0
        max_active = 0
        lock = asyncio.Lock()

        async def worker():
            nonlocal active, max_active
            async with semaphore:
                async with lock:
                    active += 1
                    max_active = max(max_active, active)
                await asyncio.sleep(0.01)
                async with lock:
                    active -= 1

        await asyncio.gather(*[worker() for _ in range(10)])
        assert max_active <= 2

    @pytest.mark.asyncio
    async def test_semaphore_guard_function(self):
        """Verify _semaphore_guard wraps function correctly."""
        semaphore = asyncio.Semaphore(1)
        calls = []

        async def test_func(x):
            calls.append(x)
            return x * 2

        wrapped = _semaphore_guard(semaphore, test_func)
        results = await asyncio.gather(wrapped(1), wrapped(2), wrapped(3))
        assert results == [2, 4, 6]
        assert len(calls) == 3

