    @pytest.mark.asyncio
    async def test_memory_usage(self, mocker, valid_config, mock_arxiv_response, mock_semantic_scholar_response):
        """Verify no memory leaks in cache."""
        import tracemalloc
        tracemalloc.start()

        pipeline = ResearchPipeline(valid_config)
        mock_session = AsyncMock()
        mock_response = AsyncMock()
        mock_response.status = 200
        mock_response.text = AsyncMock(return_value=mock_arxiv_response)
        mock_response.json = AsyncMock(return_value=mock_semantic_scholar_response)
        mock_session.get = AsyncMock(return_value=mock_response)

        with patch("aiohttp.ClientSession", return_value=mock_session):
            for i in range(10):
                await pipeline.process_papers([f"2401.{i:05d}"])

        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        assert peak < 50 * 1024 * 1024  # 50 MB peak

